settings.custom-liquid:
{% if product.metafields.custom.count %}
  <div class="product-count">
    <img src="https://cdn.shopify.com/s/files/1/0618/1925/6945/files/case-study.gif?v=1757532996" alt="Pack Icon" class="animated-gif">
    Pack of {{ product.metafields.custom.count }} Counts
  </div>
{% endif %}
<style>
.product-count {
    border: 2px solid #004A26;
    padding: 10px 10px;
    font-weight: 600;
    font-size: 16px;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    color: #004A26;
    border-radius: 8px;
    background: #f8fff8;
    animation: borderGlow 2s ease-in-out infinite;
    transition: all 0.3s ease;
}
.animated-gif {
    width: 32px;
    height: 32px;
    animation: gifBounce 3s ease-in-out infinite;
}
.product-count:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0, 74, 38, 0.3);
}
.product-wrapper:hover .animated-gif {
    animation-duration: 1.5s;
    transform: scale(1.15);
}
@keyframes borderGlow {
    0%, 100% {
        border-color: #004A26;
        box-shadow: 0 0 5px rgba(0, 74, 38, 0.3);
    }
    50% {
        border-color: #004A26;
        box-shadow: 0 0 15px rgba(0, 74, 38, 0.5);
    }
}
@keyframes gifBounce {
    0%, 100% {
        transform: translateY(0px);
    }
    50% {
        transform: translateY(-3px);
    }
}

/* Mobile Responsive */
@media (max-width: 768px) {
    .product-count {
        font-size: 14px;
        padding: 8px 8px;
        gap: 8px;
    }
    .animated-gif {
        width: 24px;
        height: 24px;
    }
}
</style>

{% comment %}
  Yeh button sirf un products par show hoga jinke tags mein 
  "customizable" ya "custom-packaging" hai
{% endcomment %}

{% if product.tags contains 'customizable' or product.tags contains 'custom-packaging' %}
  <button 
    id="customize-product-btn"
    type="button"
    style="background:#000;color:#fff;padding:20px 20px;border-radius:6px;display:inline-block;margin-top:5px;text-decoration:none;cursor:pointer;border:none;font-size:16px;font-weight:600;transition:all 0.3s ease;"
    onmouseover="this.style.background='#333'"
    onmouseout="this.style.background='#000'"
  >
    Customize This Product
  </button>

  <script>
    (function() {
      const customizeBtn = document.getElementById('customize-product-btn');

      if (customizeBtn) {
        customizeBtn.addEventListener('click', function(e) {
          e.preventDefault();

          // Customizer section ko find karo
          const customizerSection = document.querySelector('.tda-customizer-app-section-container') || 
                                     document.querySelector('[class*="customizer"]') ||
                                     document.querySelector('#tda-customizer-app-section-container-26135824466033');

          if (customizerSection) {
            // Smooth scroll with offset
            const yOffset = -80;
            const y = customizerSection.getBoundingClientRect().top + window.pageYOffset + yOffset;

            window.scrollTo({
              top: y,
              behavior: 'smooth'
            });

            // Highlight effect
            customizerSection.style.transition = 'box-shadow 0.3s';
            customizerSection.style.boxShadow = '0 0 20px rgba(0,0,0,0.3)';

            setTimeout(function() {
              customizerSection.style.boxShadow = 'none';
            }, 2000);

          } else {
            console.warn('Customizer section not found on this page');
          }
        });
      }
    })();
  </script>
{% endif %}

{% unless product.has_only_default_variant %}
  {% comment %} Product has variants - hide SKU completely {% endcomment %}
{% else %}
<style>
  .sku-label {
    background-color: #004A26;
    color: white;
    display: inline-block;
    padding: 6px;
    border-radius: 5px;
    font-size: 14px;
    margin:0;
  }
</style>
<p class="sku-label">
  SKU: {{ product.variants.first.sku }}
</p>
{% endunless %}

settings.liquid:
{% if product.metafields.custom.image1 and product.metafields.custom.image2 %}
  <style>
    .image-container {
      display: flex;
      justify-content: space-between;
      margin-left: 10%;
      margin-right: 10%;
      gap: 10px;
    }
    .image-container img {
      width: 50%;
      max-width: 100%;
      height: auto;
      object-fit: contain;
      border-radius: 8px;
    }
    @media (max-width: 767px) {
      .image-container {
        flex-direction: column;
        margin-left: 0;
        margin-right: 0;
      }
      .image-container img {
        width: 100% !important;
        margin-bottom: 15px;
      }
    }
  </style>

  <div class="image-container">
    <img src="{{ product.metafields.custom.image1 | file_url }}" alt="Image Left" />
    <img src="{{ product.metafields.custom.image2 | file_url }}" alt="Image Right" />
  </div>
{% else %}
{% endif %}

